#include <iostream>
#include <iomanip>

// Blueprint: Circle class corresponding to UML specification
class Circle {
public:
    // Data field representing state
    double radius;

    // Default constructor (no-arg constructor)
    Circle() {
        radius = 1.0;
    }

    // Parameterized constructor
    Circle(double newRadius) {
        radius = newRadius;
    }

    // Member function representing behavior
    double getArea() const {
        return radius * radius * 3.14159;
    }
};

int main() {
    // Instantiation of three distinct Circle objects
    Circle circle1(1.0);
    Circle circle2(25.0);
    Circle circle3(125.0);

    std::cout << std::fixed << std::setprecision(5);
    std::cout << "circle1 radius: " << circle1.radius 
              << ", area: " << circle1.getArea() << "\n";
    std::cout << "circle2 radius: " << circle2.radius 
              << ", area: " << circle2.getArea() << "\n";
    std::cout << "circle3 radius: " << circle3.radius 
              << ", area: " << circle3.getArea() << "\n";

    return 0;
}

#include <iostream>

// Demonstrating the Circle class from Section 9.3
class Circle {
public:
    // In C++17, default member initialization provides safe initial state
    double radius{1.0};

    // No-arg constructor
    Circle() {
        radius = 1.0;
    }

    // Constructor with a specified radius
    Circle(double newRadius) {
        radius = newRadius;
    }

    // Computes and returns the area
    double getArea() const {
        return radius * radius * 3.14159;
    }
};

int main() {
    // Create three circle objects
    Circle circle1(1.0);
    Circle circle2(25.0);
    Circle circle3(125.0);

    std::cout << "The area of the circle of radius "
              << circle1.radius << " is " << circle1.getArea() << "\n";
    std::cout << "The area of the circle of radius "
              << circle2.radius << " is " << circle2.getArea() << "\n";
    std::cout << "The area of the circle of radius "
              << circle3.radius << " is " << circle3.getArea() << "\n";

    // Modify circle2's radius to demonstrate object independence
    circle2.radius = 100.0;
    std::cout << "The area of the circle of radius "
              << circle2.radius << " is " << circle2.getArea() << "\n";

    return 0;
}
